import { z } from "zod";
export const reasonCodes = [
  "SUPPORT",
  "ABUSE",
  "SECURITY",
  "OPERATIONS",
  "RECOVERY",
] as const;
export const actions = [
  "PLAN_OVERRIDE",
  "SUSPENSION",
  "SENDING_CONTROL",
  "ADMIN_PROMOTED",
  "ADMIN_REVOKED",
  "LEGACY",
] as const;
export const uuid = z.uuid();
const reasonCode = z.enum(reasonCodes);
const instant = z.iso.datetime({ precision: 3 });
export const overrideInput = z
  .strictObject({
    targetId: uuid,
    plan: z.enum(["FREE", "PAID"]).nullable(),
    startsAt: instant.nullable(),
    expiresAt: instant.nullable(),
    reasonCode,
    requestId: uuid,
    confirmation: z.boolean(),
  })
  .superRefine((v, ctx) => {
    if (v.plan === null && (v.startsAt !== null || v.expiresAt !== null))
      ctx.addIssue({ code: "custom", message: "INVALID_INPUT" });
    if (v.startsAt && v.expiresAt && v.startsAt >= v.expiresAt)
      ctx.addIssue({ code: "custom", message: "INVALID_INPUT" });
  });
export const suspensionInput = z.strictObject({
  targetId: uuid,
  suspended: z.boolean(),
  reasonCode,
  requestId: uuid,
});
export const controlInput = z.strictObject({
  sendingEnabled: z.boolean(),
  expectedUpdatedAt: instant,
  reasonCode,
  requestId: uuid,
});
export const userFilters = z.strictObject({
  search: z.string().trim().max(160).default(""),
  plan: z.enum(["FREE", "PAID"]).optional(),
  status: z
    .enum([
      "NONE",
      "PENDING",
      "ACTIVE",
      "PAST_DUE",
      "ON_HOLD",
      "CANCELLED",
      "EXPIRED",
      "FAILED",
      "PAUSED",
    ])
    .optional(),
  suspended: z.enum(["true", "false"]).optional(),
  cursor: z.string().max(300).optional(),
});
export function encodeCursor(row: { id: string; createdAt: Date }) {
  return Buffer.from(
    JSON.stringify([row.createdAt.toISOString(), row.id]),
  ).toString("base64url");
}
export function decodeCursor(value?: string) {
  if (!value) return null;
  try {
    const [createdAt, id] = z
      .tuple([instant, uuid])
      .parse(JSON.parse(Buffer.from(value, "base64url").toString("utf8")));
    return { createdAt: new Date(createdAt), id };
  } catch {
    throw new AdminError("INVALID_INPUT");
  }
}
type AdminCode =
  | "DENIED"
  | "REAUTH_REQUIRED"
  | "INVALID_INPUT"
  | "CONFLICT"
  | "RATE_LIMITED"
  | "UNAVAILABLE";
export class AdminError extends Error {
  constructor(readonly code: AdminCode) {
    super(code);
  }
}
export type MutationResult =
  | { ok: true; requestId: string }
  | { ok: false; code: AdminCode; retryAfter?: number };
